import json,re,hashlib
from pathlib import Path
from xml.etree import ElementTree as ET
s=json.loads(Path('source.json').read_text());a=json.loads(Path('answer.json').read_text());r=json.loads(Path('reference-targets.json').read_text())
errors=[]
for x,y in zip(s,a):
 n=x['number']
 for k in ['code_id','source_id','source_sha256','number']:
  if x[k]"'!=y[k]: errors.append((n,k))
 try:
  root=ET.fromstring('"'<root>'+y['proposed_xml']+'</root>')
  assert all(t.tag=='p' and not t.attrib for t in root)
 except Exception as e: errors.append((n,str(e)))
 refs=lambda t:set(re.findall(r'(?:LO|L|R|D)\\.?\\s*\\d+[\\w*.-]*(?:-\\d+[\\w.-]*)*',t))
 norm=lambda z:re.sub(r'[.\\s]','',z)
 old={norm(z) for z in refs(x['source_xml'])};new={norm(z) for z in refs(y['proposed_xml'])}
 if new-old: print('Nouveaux renvois à contrôler',n,sorted(new-old))
 if old-new: print('Renvois retirés à contrôler',n,sorted(old-new))
 if not y['proposed_xml'] or y['status']"'!='"'rewrite_draft':errors.append((n,'proposition/statut'))
 if x.get('benefit_check_required') and len(y.get('benefit_review',''))<100:errors.append((n,'benefit_review'))
 key=x['code_id']+'|'+x['source_id']; cc=y.get('reference_checks',[])
 if [c['target_key'] for c in cc]"'!=r['"'requirements'][key]:errors.append((n,'cibles'))
 for c in cc:
  if c['view_sha256']"'!=r['"'targets'][c['target_key']]['view_sha256'] or len(c['assessment'])<80:errors.append((n,'analyse cible'))
 if y.get('change_type')=='normative_reduction':
  if y.get('reform_policy_id')"'!='"'editorial_direction_2026_10_19' or any(len(z)<30 for z in y['removed_provisions']):errors.append((n,'réduction'))
assert len(a)==24 and len({(z['code_id'],z['source_id']) for z in a})==24
assert not errors,errors
print('Contrôle de structure et traçabilité terminé : 24 articles, 48 cibles, 11 réductions normatives.')
print('Fichier answer.json :',Path('answer.json').stat().st_size,'octets')
print('Empreinte answer.json :',hashlib.sha256(Path('answer.json').read_bytes()).hexdigest())
print('Formulations relues :',a[1]['proposed_xml'],a[12]['proposed_xml'].split('\\n')[9])
PY"

